--
-- Name: create_document_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_document_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 当文档内容发生变化时，自动创建新版本
    IF OLD.content IS DISTINCT FROM NEW.content OR OLD.title IS DISTINCT FROM NEW.title THEN
            document_id, 
            version_number, 
            title, 
            content, 
            changes_summary, 
            metadata,
            created_by
        )
        VALUES (
            NEW.id,
            NEW.version,
            NEW.title,
            NEW.content,
            CASE 
                WHEN OLD.title IS DISTINCT FROM NEW.title THEN '标题更新'
                WHEN OLD.content IS DISTINCT FROM NEW.content THEN '内容更新'
                ELSE '文档更新'
            END,
            NEW.metadata,
            NEW.owner_id
        );
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: create_timeline_events_batch(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_timeline_events_batch(events jsonb) RETURNS TABLE(id bigint, event_type character varying, task_id bigint, success boolean, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_record RECORD;
    inserted_id BIGINT;
    error_msg TEXT;
BEGIN
    FOR event_record IN 
        SELECT * FROM jsonb_to_recordset(events) AS x(
            task_id BIGINT,
            event_type VARCHAR(50),
            description TEXT,
            user_id BIGINT,
            metadata JSONB,
            username VARCHAR(100),
            task_title VARCHAR(500),
            project_id BIGINT,
            correlation_id VARCHAR(100),
            parent_event_id BIGINT,
            severity VARCHAR(20),
            category VARCHAR(20)
        )
    LOOP
        BEGIN
                task_id, event_type, description, user_id, metadata,
                username, task_title, project_id, correlation_id,
                parent_event_id, severity, category
            ) VALUES (
                event_record.task_id,
                event_record.event_type,
                event_record.description,
                event_record.user_id,
                COALESCE(event_record.metadata, '{}'::JSONB),
                event_record.username,
                event_record.task_title,
                event_record.project_id,
                event_record.correlation_id,
                event_record.parent_event_id,
                COALESCE(event_record.severity, 'info'),
                COALESCE(event_record.category, 'user')
            ) RETURNING task_timeline_events.id INTO inserted_id;
            
            RETURN QUERY SELECT 
                inserted_id,
                event_record.event_type,
                event_record.task_id,
                TRUE as success,
                NULL::TEXT as error_message;
                
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS error_msg = MESSAGE_TEXT;
            RETURN QUERY SELECT 
                NULL::BIGINT,
                event_record.event_type,
                event_record.task_id,
                FALSE as success,
                error_msg;
        END;
    END LOOP;
END;
$$;


--
-- Name: generate_api_key_prefix(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_api_key_prefix(key_type text DEFAULT 'general'::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    CASE key_type
        WHEN 'admin' THEN RETURN 'ak_admin_';
        WHEN 'user' THEN RETURN 'ak_user_';
        WHEN 'service' THEN RETURN 'ak_svc_';
        WHEN 'readonly' THEN RETURN 'ak_ro_';
        ELSE RETURN 'ak_';
    END CASE;
END;
$$;


--
-- Name: get_enhanced_task_timeline(bigint, text[], bigint[], text[], text[], timestamp with time zone, timestamp with time zone, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_enhanced_task_timeline(p_task_id bigint, p_event_types text[] DEFAULT NULL::text[], p_user_ids bigint[] DEFAULT NULL::bigint[], p_categories text[] DEFAULT NULL::text[], p_severities text[] DEFAULT NULL::text[], p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_include_system boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id bigint, task_id bigint, event_type character varying, event_date timestamp with time zone, description text, user_id bigint, metadata jsonb, username character varying, task_title character varying, project_id bigint, correlation_id character varying, parent_event_id bigint, severity character varying, category character varying, created_at timestamp with time zone, updated_at timestamp with time zone, user_username character varying, user_email character varying, current_task_title character varying, current_task_status character varying, project_name character varying, seconds_since_previous_event numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        tte.id,
        tte.task_id,
        tte.event_type,
        tte.event_date,
        tte.description,
        tte.user_id,
        tte.metadata,
        tte.username,
        tte.task_title,
        tte.project_id,
        tte.correlation_id,
        tte.parent_event_id,
        tte.severity,
        tte.category,
        tte.created_at,
        tte.updated_at,
        tte.user_username,
        tte.user_email,
        tte.current_task_title,
        tte.current_task_status,
        tte.project_name,
        tte.seconds_since_previous_event
    FROM v_enhanced_timeline_events tte
    WHERE tte.task_id = p_task_id
        AND (p_event_types IS NULL OR tte.event_type = ANY(p_event_types))
        AND (p_user_ids IS NULL OR tte.user_id = ANY(p_user_ids))
        AND (p_categories IS NULL OR tte.category = ANY(p_categories))
        AND (p_severities IS NULL OR tte.severity = ANY(p_severities))
        AND (p_start_date IS NULL OR tte.event_date >= p_start_date)
        AND (p_end_date IS NULL OR tte.event_date <= p_end_date)
        AND (p_include_system = TRUE OR tte.category != 'system')
    ORDER BY tte.event_date DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: get_task_ancestors(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_task_ancestors(task_id integer) RETURNS TABLE(id integer, title character varying, level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH task_path AS (
        SELECT path FROM tasks WHERE tasks.id = task_id AND deleted_at IS NULL
    )
    SELECT t.id, t.title, nlevel(tp.path) - nlevel(t.path) as level
    FROM tasks t, task_path tp
    WHERE t.path @> tp.path
    AND t.deleted_at IS NULL
    ORDER BY nlevel(t.path);
END;
$$;


--
-- Name: get_task_children(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_task_children(task_id integer) RETURNS TABLE(id integer, title character varying, sort_order integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT t.id, t.title, t.sort_order
    FROM tasks t
    WHERE t.parent_id = task_id
    AND t.deleted_at IS NULL
    ORDER BY t.sort_order, t.id;
END;
$$;


--
-- Name: get_task_descendants(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_task_descendants(task_id integer) RETURNS TABLE(id integer, title character varying, level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH task_path AS (
        SELECT path FROM tasks WHERE tasks.id = task_id AND deleted_at IS NULL
    )
    SELECT t.id, t.title, nlevel(t.path) - nlevel(tp.path) as level
    FROM tasks t, task_path tp
    WHERE tp.path @> t.path
    AND t.path != tp.path  -- 排除自己
    AND t.deleted_at IS NULL
    ORDER BY t.path;
END;
$$;


