CREATE FUNCTION public.update_expired_impersonation_sessions() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated_count INTEGER;
BEGIN
    UPDATE impersonation_sessions 
    SET status = 'expired', updated_at = NOW()
    WHERE status = 'active' 
      AND expires_at < NOW();
    
    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$$;


