--
-- Name: update_task_path(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_task_path() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_path ltree;
    new_depth integer;
BEGIN
    -- 计算新路径
    new_path := calculate_task_path(NEW.id);
    
    -- 计算深度
    IF new_path IS NOT NULL THEN
        new_depth := nlevel(new_path) - 1;
    ELSE
        new_depth := 0;
    END IF;
    
    -- 更新路径和深度
    NEW.path := new_path;
    NEW.depth := new_depth;
    
    RETURN NEW;
END;
$$;


