--
-- Name: active_api_keys; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_api_keys AS
 SELECT ak.id,
    ak.name,
    ak.description,
    ak.key_hash,
    ak.key_prefix,
    ak.secret_hash,
    ak.permissions,
    ak.scope_projects,
    ak.scope_users,
    ak.rate_limit_count,
    ak.rate_limit_window,
    ak.daily_quota,
    ak.monthly_quota,
    ak.is_active,
    ak.expires_at,
    ak.last_used_at,
    ak.usage_count,
    ak.allowed_ips,
    ak.allowed_domains,
    ak.user_agent_pattern,
    ak.created_by,
    ak.created_at,
    ak.updated_by,
    ak.updated_at,
    ak.deleted_at,
    ak.metadata,
    ak.tags,
    u.username AS created_by_username,
    u.email AS created_by_email
   FROM (public.api_keys ak
     JOIN public.users u ON ((ak.created_by = u.id)))
  WHERE ((ak.is_active = true) AND ((ak.expires_at IS NULL) OR (ak.expires_at > now())) AND (ak.deleted_at IS NULL));


