    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_impersonation_dates CHECK ((started_at < expires_at)),
    CONSTRAINT chk_impersonation_ended CHECK (((ended_at IS NULL) OR (ended_at >= started_at))),
    CONSTRAINT chk_impersonation_status CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'expired'::character varying, 'ended'::character varying])::text[])))
);


