--
-- Name: task_hierarchy_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.task_hierarchy_view AS
 WITH RECURSIVE task_tree AS (
         SELECT tasks.id,
            tasks.title,
            tasks.parent_id,
            tasks.path,
            tasks.depth,
            ARRAY[tasks.id] AS path_array,
            (tasks.title)::text AS path_string
           FROM public.tasks
          WHERE ((tasks.parent_id IS NULL) AND (tasks.deleted_at IS NULL))
        UNION ALL
         SELECT t.id,
            t.title,
            t.parent_id,
            t.path,
            t.depth,
            (tt.path_array || t.id),
            ((tt.path_string || ' > '::text) || (t.title)::text) AS text
           FROM (public.tasks t
             JOIN task_tree tt ON ((t.parent_id = tt.id)))
          WHERE (t.deleted_at IS NULL)
        )
 SELECT id,
    title,
    parent_id,
    path,
    depth,
    path_array,
    path_string,
    array_length(path_array, 1) AS hierarchy_level
   FROM task_tree
  ORDER BY path;


