    sync_mode character varying(20) DEFAULT 'auto'::character varying,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp without time zone,
    CONSTRAINT task_key_result_associations_sync_mode_check CHECK (((sync_mode)::text = ANY ((ARRAY['auto'::character varying, 'manual'::character varying])::text[]))),
    CONSTRAINT task_key_result_associations_weight_check CHECK (((weight >= (0)::numeric) AND (weight <= (100)::numeric)))
