ALTER SEQUENCE public.users_id_seq OWNED BY public.users.id;


--
-- Name: v_enhanced_timeline_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_enhanced_timeline_events AS
 SELECT tte.id,
    tte.task_id,
    tte.event_type,
    tte.event_date,
    tte.description,
    tte.user_id,
    tte.metadata,
    tte.username,
    tte.task_title,
    tte.project_id,
    tte.correlation_id,
    tte.parent_event_id,
    tte.severity,
    tte.category,
    tte.created_at,
    tte.updated_at,
    u.username AS user_username,
    u.email AS user_email,
    t.title AS current_task_title,
    t.status AS current_task_status,
    t.priority AS current_task_priority,
    p.name AS project_name,
    parent_tte.event_type AS parent_event_type,
    parent_tte.description AS parent_event_description,
    EXTRACT(epoch FROM (tte.event_date - lag(tte.event_date) OVER (PARTITION BY tte.task_id ORDER BY tte.event_date))) AS seconds_since_previous_event
   FROM ((((public.task_timeline_events tte
     LEFT JOIN public.users u ON ((tte.user_id = u.id)))
     LEFT JOIN public.tasks t ON ((tte.task_id = t.id)))
     LEFT JOIN public.projects p ON ((tte.project_id = p.id)))
     LEFT JOIN public.task_timeline_events parent_tte ON ((tte.parent_event_id = parent_tte.id)));


--
-- Name: v_legacy_companies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_legacy_companies AS
 SELECT id,
    company_name,
    industry,
    status,
