CREATE VIEW public.v_legacy_customers AS
 SELECT id,
    company_name AS name,
    company_name AS company,
    industry,
    status,
    priority,
    created_at,
    updated_at,
    'MIGRATED_FROM_CUSTOMERS'::text AS migration_note
   FROM public.customers c
  WHERE (deleted_at IS NULL);


--
-- Name: v_permission_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_permission_analytics AS
 SELECT p.module,
    count(*) AS total_permissions,
    count(
        CASE
            WHEN (rp.is_granted = true) THEN 1
            ELSE NULL::integer
        END) AS granted_count,
    count(DISTINCT rp.role_id) AS roles_with_permission,
    count(DISTINCT mv.company_user_id) AS users_with_permission,
    round((((count(
        CASE
            WHEN (rp.is_granted = true) THEN 1
            ELSE NULL::integer
        END))::numeric * 100.0) / (NULLIF(count(*), 0))::numeric), 2) AS grant_percentage
   FROM ((public.permissions p
     LEFT JOIN public.role_permissions rp ON ((p.id = rp.permission_id)))
     LEFT JOIN public.mv_user_effective_permissions mv ON (((p.permission_code)::text = (mv.permission_code)::text)))
  WHERE (p.is_active = true)
  GROUP BY p.module
  ORDER BY (count(*)) DESC;


--
-- Name: v_position_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_position_permissions AS
 SELECT p.id AS position_id,
    p.position_name,
    p.enterprise_id,
    COALESCE(jsonb_agg(DISTINCT jsonb_build_object('source', perms.perm_source, 'permission_code', perms.perm_code, 'permission_name', perms.perm_name, 'permission_id', perms.perm_id)) FILTER (WHERE (perms.perm_code IS NOT NULL)), '[]'::jsonb) AS all_permissions
   FROM (public.enterprise_positions p
     LEFT JOIN LATERAL ( SELECT 'position_base'::text AS perm_source,
            jsonb_array_elements_text(p.base_permissions) AS perm_code,
            perm.permission_name AS perm_name,
            perm.id AS perm_id
           FROM public.permissions perm
          WHERE ((perm.permission_code)::text IN ( SELECT jsonb_array_elements_text(p.base_permissions) AS jsonb_array_elements_text))
        UNION ALL
         SELECT 'position_additional'::text AS perm_source,
            jsonb_array_elements_text(p.additional_permissions) AS perm_code,
            perm.permission_name AS perm_name,
            perm.id AS perm_id
           FROM public.permissions perm
          WHERE ((perm.permission_code)::text IN ( SELECT jsonb_array_elements_text(p.additional_permissions) AS jsonb_array_elements_text))
        UNION ALL
         SELECT 'role_template'::text AS perm_source,
            perm.permission_code AS perm_code,
            perm.permission_name AS perm_name,
            perm.id AS perm_id
           FROM (public.role_template_permissions rtp
             JOIN public.permissions perm ON ((rtp.permission_id = perm.id)))
          WHERE ((rtp.template_id = p.role_template_id) AND (perm.is_active = true))) perms ON (true))
  WHERE (p.deleted_at IS NULL)
  GROUP BY p.id, p.position_name, p.enterprise_id;


--
-- Name: VIEW v_position_permissions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_position_permissions IS '岗位权限继承视图';


--
-- Name: v_project_user_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_project_user_permissions AS
 SELECT cupp.id,
    cupp.company_user_id,
    cu.name AS user_name,
    cu.email AS user_email,
    cupp.project_id,
    cupp.can_view_project,
    cupp.can_edit_project,
    cupp.can_delete_project,
    cupp.can_manage_tasks,
    cupp.can_view_financials,
    cupp.can_manage_members,
    cupp.permission_start_date,
    cupp.permission_end_date,
        CASE
            WHEN ((cupp.permission_end_date IS NULL) OR (cupp.permission_end_date > CURRENT_TIMESTAMP)) THEN true
            ELSE false
        END AS is_active
   FROM (public.company_user_project_permissions cupp
     JOIN public.company_users cu ON ((cupp.company_user_id = cu.id)))
  WHERE ((cu.status)::text = 'active'::text);


--
-- Name: v_role_permission_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_role_permission_summary AS
 SELECT cr.id AS role_id,
    cr.role_code,
    cr.role_name,
    cr.role_description,
    count(p.id) AS total_permissions,
    count(
        CASE
            WHEN (rp.is_granted = true) THEN 1
            ELSE NULL::integer
        END) AS granted_permissions,
    count(
        CASE
            WHEN (rp.is_granted = false) THEN 1
            ELSE NULL::integer
        END) AS denied_permissions,
    array_agg(DISTINCT p.module ORDER BY p.module) AS modules,
    array_agg(p.permission_code ORDER BY p.permission_code) FILTER (WHERE (rp.is_granted = true)) AS granted_permission_codes
   FROM ((public.company_roles cr
     LEFT JOIN public.role_permissions rp ON ((cr.id = rp.role_id)))
     LEFT JOIN public.permissions p ON (((rp.permission_id = p.id) AND (p.is_active = true))))
  WHERE (cr.is_active = true)
  GROUP BY cr.id, cr.role_code, cr.role_name, cr.role_description;


--
-- Name: v_system_role_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_system_role_permissions AS
 SELECT r.id AS role_id,
    r.role_code,
    r.role_name,
    r.role_description,
    count(rp.permission_id) AS permission_count,
    r.is_system_role,
    r.is_active,
    r.created_at,
    r.updated_at
   FROM (public.company_roles r
     LEFT JOIN public.role_permissions rp ON (((r.id = rp.role_id) AND (rp.is_granted = true))))
  WHERE (r.is_system_role = true)
  GROUP BY r.id, r.role_code, r.role_name, r.role_description, r.is_system_role, r.is_active, r.created_at, r.updated_at
  ORDER BY r.role_code;


--
-- Name: v_timeline_event_statistics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_timeline_event_statistics AS
 WITH daily_stats AS (
         SELECT date(task_timeline_events.event_date) AS event_date,
            task_timeline_events.event_type,
            task_timeline_events.category,
            task_timeline_events.severity,
            task_timeline_events.user_id,
            task_timeline_events.project_id,
            count(*) AS event_count
           FROM public.task_timeline_events
          WHERE (task_timeline_events.event_date >= (CURRENT_DATE - '30 days'::interval))
          GROUP BY (date(task_timeline_events.event_date)), task_timeline_events.event_type, task_timeline_events.category, task_timeline_events.severity, task_timeline_events.user_id, task_timeline_events.project_id
        ), user_activity AS (
         SELECT task_timeline_events.user_id,
            task_timeline_events.username,
            count(*) AS total_events,
            count(DISTINCT task_timeline_events.task_id) AS tasks_touched,
            count(DISTINCT date(task_timeline_events.event_date)) AS active_days
           FROM public.task_timeline_events
          WHERE ((task_timeline_events.event_date >= (CURRENT_DATE - '30 days'::interval)) AND (task_timeline_events.user_id IS NOT NULL))
          GROUP BY task_timeline_events.user_id, task_timeline_events.username
        )
 SELECT 'summary'::text AS stat_type,
    json_build_object('total_events', ( SELECT count(*) AS count
           FROM public.task_timeline_events
          WHERE (task_timeline_events.event_date >= (CURRENT_DATE - '30 days'::interval))), 'total_users', ( SELECT count(DISTINCT task_timeline_events.user_id) AS count
           FROM public.task_timeline_events
          WHERE ((task_timeline_events.event_date >= (CURRENT_DATE - '30 days'::interval)) AND (task_timeline_events.user_id IS NOT NULL))), 'total_tasks', ( SELECT count(DISTINCT task_timeline_events.task_id) AS count
           FROM public.task_timeline_events
          WHERE (task_timeline_events.event_date >= (CURRENT_DATE - '30 days'::interval))), 'total_projects', ( SELECT count(DISTINCT task_timeline_events.project_id) AS count
           FROM public.task_timeline_events
          WHERE ((task_timeline_events.event_date >= (CURRENT_DATE - '30 days'::interval)) AND (task_timeline_events.project_id IS NOT NULL)))) AS statistics;


--
-- Name: v_today_focus_tasks; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_today_focus_tasks AS
 SELECT dft.id,
    dft.task_id,
    dft.user_id,
    dft.project_id,
    dft.focus_date,
    dft.sort_order,
    dft.priority_level,
    dft.is_auto_suggested,
    dft.suggestion_reason,
    dft.status,
    dft.estimated_duration_minutes,
    dft.user_notes,
    dft.created_at,
    dft.updated_at,
    t.title AS task_title,
    t.description AS task_description,
    t.status AS task_status,
    t.priority AS task_priority,
    t.due_date AS task_due_date,
    t.assignee_id AS task_assignee_id,
    p.name AS project_name,
    p.project_number AS project_code
   FROM ((public.daily_focus_tasks dft
     JOIN public.tasks t ON ((dft.task_id = t.id)))
     JOIN public.projects p ON ((dft.project_id = p.id)))
  WHERE ((dft.focus_date = CURRENT_DATE) AND ((dft.status)::text = 'active'::text) AND (t.deleted_at IS NULL));


--
-- Name: v_user_effective_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_effective_permissions AS
 SELECT eu.id AS user_id,
    eu.username,
    eu.enterprise_id,
    COALESCE(jsonb_agg(DISTINCT jsonb_build_object('source', user_perms.perm_source, 'permission_code', user_perms.permission_code, 'permission_name', user_perms.permission_name, 'granted_through', user_perms.granted_through, 'permission_id', user_perms.permission_id)) FILTER (WHERE (user_perms.permission_code IS NOT NULL)), '[]'::jsonb) AS effective_permissions
   FROM (public.enterprise_users eu
     LEFT JOIN LATERAL ( SELECT 'enterprise_role'::text AS perm_source,
            perm.permission_code,
            perm.permission_name,
            er.role_name AS granted_through,
            perm.id AS permission_id
           FROM (((public.enterprise_user_roles eur
             JOIN public.enterprise_roles er ON ((eur.role_id = er.id)))
             CROSS JOIN LATERAL jsonb_array_elements_text(er.permissions) role_perm_code(value))
             JOIN public.permissions perm ON (((perm.permission_code)::text = role_perm_code.value)))
          WHERE ((eur.enterprise_user_id = eu.id) AND (eur.is_active = true) AND (er.is_active = true) AND (perm.is_active = true))) user_perms ON (true))
  WHERE (eu.deleted_at IS NULL)
  GROUP BY eu.id, eu.username, eu.enterprise_id;


--
-- Name: v_user_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_permissions AS
 SELECT cu.id AS user_id,
    cu.name AS user_name,
    cu.email AS user_email,
    cu.status AS user_status,
    cr.role_code,
    cr.role_name,
    p.permission_code,
    p.permission_name,
    p.module,
    p.resource,
    p.action,
    rp.is_granted AS role_granted,
        CASE
            WHEN (cu.custom_permissions ? (p.permission_code)::text) THEN ((cu.custom_permissions ->> (p.permission_code)::text))::boolean
            ELSE NULL::boolean
        END AS custom_override,
        CASE
            WHEN (cu.custom_permissions ? (p.permission_code)::text) THEN ((cu.custom_permissions ->> (p.permission_code)::text))::boolean
            ELSE rp.is_granted
        END AS effective_permission
   FROM (((public.company_users cu
     LEFT JOIN public.company_roles cr ON ((cu.role_id = cr.id)))
     LEFT JOIN public.role_permissions rp ON (((cr.id = rp.role_id) AND (rp.is_granted = true))))
     LEFT JOIN public.permissions p ON ((rp.permission_id = p.id)))
  WHERE (((cu.status)::text = 'active'::text) AND (cr.is_active = true) AND (p.is_active = true));


--
-- Name: work_note_folders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_note_folders (
    id integer NOT NULL,
    name character varying(100) NOT NULL,
    description text,
    parent_id integer,
    owner_id integer NOT NULL,
    project_id integer,
    visibility character varying(20) DEFAULT 'private'::character varying NOT NULL,
    color character varying(7),
    icon character varying(50),
    sort_order integer DEFAULT 0 NOT NULL,
    created_by integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT work_note_folders_name_not_empty CHECK ((length(TRIM(BOTH FROM name)) > 0)),
    CONSTRAINT work_note_folders_visibility_check CHECK (((visibility)::text = ANY ((ARRAY['private'::character varying, 'team'::character varying, 'public'::character varying])::text[]))),
    CONSTRAINT work_note_folders_visibility_valid CHECK (((visibility)::text = ANY ((ARRAY['private'::character varying, 'team'::character varying, 'public'::character varying])::text[])))
);


